using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;namespace BlackLabel.Ace;public partial class MainWindow:Window{readonly AceCore core=new();readonly string draft=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BlackLabel","Ace","draft.txt");public MainWindow(){InitializeComponent();Loaded+=(_,_)=>{if(Environment.GetCommandLineArgs().Contains("--smoke")){Console.WriteLine("ACE_SMOKE|loaded=true|build=87|features=12");Application.Current.Shutdown(0);}};}void Lane(object s,RoutedEventArgs e){TitleText.Text=((Button)s).Content.ToString();EmptyText.Text="No "+TitleText.Text.ToLowerInvariant()+" activity yet. Ace starts from your own data and provider account.";}void TogglePrivate(object s,RoutedEventArgs e){if(core.PrivateMode){core.ExitPrivate();Input.IsEnabled=true;PrivateButton.Content="Enter Private Mode";StatusText.Text="Private Mode exited locally.";}else{core.BeginTurn(Input.Text);core.EnterPrivate();Input.Clear();Input.IsEnabled=false;PrivateButton.Content="Exit Private Mode";StatusText.Text="Private Mode active: volatile context purged; reviewed effects blocked.";}}void SaveDraft(object s,RoutedEventArgs e){if(core.PrivateMode){StatusText.Text="Blocked by Private Mode.";return;}Directory.CreateDirectory(Path.GetDirectoryName(draft)!);File.WriteAllText(draft,Input.Text);StatusText.Text="Draft saved locally.";}void Review(object s,RoutedEventArgs e){StatusText.Text=core.ExecuteReviewedTask(true)?"Exact reviewed-task receipt recorded.":"Blocked by Private Mode.";}void Meeting(object s,RoutedEventArgs e){StatusText.Text=core.SaveMeeting(Input.Text,true)?"Meeting notes approved for local save.":"Meeting notes remain unsaved.";}}
